ALTER TABLE `BackgroundJob` MODIFY `type` ENUM('SCHEDULED_PUBLISH','ANALYTICS_AGGREGATE','MAINTENANCE','EMAIL','IMAGE_PROCESS','LINK_CHECK','AI_TASK','WEBHOOK_DELIVERY') NOT NULL;
ALTER TABLE `User` ADD COLUMN `phase30_placeholder` TINYINT NULL;
ALTER TABLE `User` DROP COLUMN `phase30_placeholder`;
CREATE TABLE `WebhookEndpoint` (`id` VARCHAR(191) NOT NULL,`name` VARCHAR(191) NOT NULL,`url` TEXT NOT NULL,`secret` TEXT NOT NULL,`events` JSON NOT NULL,`active` BOOLEAN NOT NULL DEFAULT true,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,INDEX `WebhookEndpoint_active_updatedAt_idx`(`active`,`updatedAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `WebhookDelivery` (`id` VARCHAR(191) NOT NULL,`endpointId` VARCHAR(191) NOT NULL,`event` VARCHAR(191) NOT NULL,`eventId` VARCHAR(191) NOT NULL,`payload` JSON NOT NULL,`statusCode` INTEGER NULL,`succeeded` BOOLEAN NOT NULL DEFAULT false,`attempts` INTEGER NOT NULL DEFAULT 0,`lastError` TEXT NULL,`deliveredAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE INDEX `WebhookDelivery_endpointId_eventId_key`(`endpointId`,`eventId`),INDEX `WebhookDelivery_succeeded_createdAt_idx`(`succeeded`,`createdAt`),INDEX `WebhookDelivery_endpointId_createdAt_idx`(`endpointId`,`createdAt`),PRIMARY KEY (`id`),CONSTRAINT `WebhookDelivery_endpointId_fkey` FOREIGN KEY (`endpointId`) REFERENCES `WebhookEndpoint`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Announcement` (`id` VARCHAR(191) NOT NULL,`message` TEXT NOT NULL,`linkUrl` TEXT NULL,`linkLabel` VARCHAR(191) NULL,`enabled` BOOLEAN NOT NULL DEFAULT false,`dismissible` BOOLEAN NOT NULL DEFAULT true,`startAt` DATETIME(3) NULL,`endAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,INDEX `Announcement_enabled_startAt_endAt_idx`(`enabled`,`startAt`,`endAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `FeatureFlag` (`id` VARCHAR(191) NOT NULL,`key` VARCHAR(191) NOT NULL,`enabled` BOOLEAN NOT NULL DEFAULT false,`description` TEXT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE INDEX `FeatureFlag_key_key`(`key`),INDEX `FeatureFlag_enabled_idx`(`enabled`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `SettingHistory` (`id` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NULL,`group` VARCHAR(191) NOT NULL,`key` VARCHAR(191) NOT NULL,`oldValue` JSON NULL,`newValue` JSON NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `SettingHistory_key_createdAt_idx`(`key`,`createdAt`),INDEX `SettingHistory_userId_createdAt_idx`(`userId`,`createdAt`),PRIMARY KEY (`id`),CONSTRAINT `SettingHistory_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE SET NULL ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
